const $=s=>document.querySelector(s), app=$('#app'), modalRoot=$('#modalRoot');
const STORE='mpiDarsanaLocal_v8';
const initial={identity:null,avatar:'🦊',completed:[],feedbackDone:[],reflections:{},quiz:null,certificate:null,reflectedAfterQuiz:false,conversationDone:false};
let state=loadState(), route='intro', introStep=0, activeLesson=0, feedbackAnswers={}, quizIndex=0, quizAnswers={}, quizStart=0, quizTimer=null, quizSubmitted=false, pendingRoute=null, practiceIndex=0, practiceAnswers={}, identityReturnRoute='percakapan', activityMode='hub', activityIndex=0, activityAnswers={}, scrambleAnswer='', matchSelected=null, matchedPairs=[];
function loadState(){try{return {...initial,...JSON.parse(localStorage.getItem(STORE)||'{}')}}catch(e){return {...initial}}}
function saveState(){try{localStorage.setItem(STORE,JSON.stringify(state))}catch(e){console.warn('Penyimpanan lokal tidak tersedia',e)}}

// Audio: efek jawaban dan musik lembut dimulai setelah interaksi pertama pengguna
// karena browser membatasi pemutaran audio otomatis sebelum ada interaksi.
let audioContext=null, soundEffectsEnabled=true, musicEnabled=false, musicTimer=null, musicStep=0, activeMusicNodes=[];
function getAudioContext(){if(!audioContext){const Ctx=window.AudioContext||window.webkitAudioContext;if(Ctx)audioContext=new Ctx()}if(audioContext&&audioContext.state==='suspended')audioContext.resume().catch(()=>{});return audioContext}
function playTone(freq,duration,kind='sine',volume=.045,delay=0){if(!soundEffectsEnabled)return;const ctx=getAudioContext();if(!ctx)return;const now=ctx.currentTime+delay,osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=kind;osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(volume,now+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(gain);gain.connect(ctx.destination);osc.start(now);osc.stop(now+duration+.03)}
function playAnswerSound(correct){if(!soundEffectsEnabled)return;if(correct){playTone(659.25,.18,'sine',.055);playTone(880,.27,'sine',.045,.1)}else{playTone(190,.18,'triangle',.035);try{if('vibrate'in navigator)navigator.vibrate([80,35,80])}catch(e){}}}
function playMusicNote(){if(!musicEnabled)return;const ctx=getAudioContext();if(!ctx)return;const notes=[261.63,329.63,392,329.63,293.66,349.23,440,349.23];const now=ctx.currentTime,osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=notes[musicStep%notes.length];musicStep++;gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.009,now+.22);gain.gain.setValueAtTime(.009,now+.72);gain.gain.exponentialRampToValueAtTime(.0001,now+1.55);osc.connect(gain);gain.connect(ctx.destination);osc.start(now);osc.stop(now+1.6);activeMusicNodes.push(osc);activeMusicNodes=activeMusicNodes.slice(-3)}
function startAmbientAudio(){if(musicEnabled)return;musicEnabled=true;getAudioContext();playMusicNote();musicTimer=setInterval(playMusicNote,1650)}
function initAudioOnFirstInteraction(){startAmbientAudio();document.removeEventListener('pointerdown',initAudioOnFirstInteraction);document.removeEventListener('keydown',initAudioOnFirstInteraction)}
document.addEventListener('pointerdown',initAudioOnFirstInteraction,{once:true});document.addEventListener('keydown',initAudioOnFirstInteraction,{once:true});
const lessons=[
 {name:'Nyāya',icon:'🔎',figure:'Rsi Gautama',focus:'Logika, penalaran, dan cara memperoleh pengetahuan yang benar.',intro:'Nyāya menekankan penggunaan logika, analisis, dan pembuktian untuk memperoleh pengetahuan yang benar.',sections:[['Empat unsur pengetahuan','Pramātā adalah subjek yang mengetahui, Prameya adalah objek yang diketahui, Pramiti adalah pengetahuan yang diperoleh, dan Pramāṇa adalah cara memperoleh pengetahuan.'],['Dua belas Prameya','Atman (roh), Sarira (badan), Indriya (indra), Artha (objek indra), Buddhi (kecerdasan), Manas (pikiran), Pravṛtti (kegiatan), Dosa (kesalahan), Pretyabhava (kelahiran kembali), Phala (hasil perbuatan), Duhkha (penderitaan), dan Apavarga (pembebasan).'],['Catur Pramāṇa','Pratyakṣa: pengamatan langsung. Anumāna: penyimpulan. Upamāna: perbandingan. Śabda: kesaksian atau sumber yang dapat dipercaya.'],['Penerapan sehari-hari','Memeriksa sumber dan bukti, membandingkan informasi, lalu menarik kesimpulan secara hati-hati.']],apply:'Saat menerima informasi, periksa sumber dan bukti, bandingkan informasi, lalu simpulkan secara hati-hati.',feedback:[['Nyāya dikaitkan dengan tokoh…',['Rsi Gautama','Rsi Kanada','Rsi Jaimini'],0,'Nyāya dikaitkan dengan Rsi Gautama.'],['Pratyakṣa Pramāṇa berarti…',['Menyimpulkan','Pengamatan langsung','Membandingkan'],1,'Pratyakṣa adalah pengetahuan melalui pengamatan langsung.'],['Contoh penerapan Nyāya adalah…',['Meneruskan kabar tanpa memeriksa','Menarik kesimpulan berdasarkan bukti','Mengabaikan sumber informasi'],1,'Nyāya mendorong pemeriksaan alasan dan bukti.']]},
 {name:'Vaiśeṣika',icon:'🪨',figure:'Rsi Kanada',focus:'Hakikat benda dan unsur penyusun alam melalui kategori Padārtha.',intro:'Vaiśeṣika berusaha memahami realitas melalui Padārtha, yaitu kategori untuk menjelaskan benda dan keberadaan.',sections:[['Tujuh Padārtha','Dravya: substansi. Guṇa: sifat. Karma: gerak atau kegiatan. Sāmānya: sifat umum. Viśeṣa: kekhususan. Samavāya: keterpaduan atau hubungan inheren. Abhāva: ketidakadaan.'],['Penyebab penciptaan','Dalam bahan pembelajaran, Nimitta dijelaskan sebagai penyebab efisien dan Upādāna sebagai penyebab material.'],['Cara memahami realitas','Pengamatan terhadap benda, sifat, gerak, persamaan, dan perbedaan disusun ke dalam kategori agar realitas lebih mudah dipahami.'],['Penerapan sehari-hari','Mengamati suatu fenomena, mengelompokkan hasil pengamatan berdasarkan ciri, lalu mencatat persamaan dan perbedaannya.']],apply:'Saat mengamati tumbuhan, kelompokkan ciri daun, batang, dan akar, lalu catat persamaan serta perbedaannya.',feedback:[['Vaiśeṣika dikaitkan dengan…',['Rsi Kapila','Rsi Kanada','Maharsi Patanjali'],1,'Vaiśeṣika dikaitkan dengan Rsi Kanada.'],['Padārtha adalah…',['Kategori untuk menjelaskan realitas','Delapan tahapan Yoga','Empat cara memperoleh pengetahuan'],0,'Padārtha merupakan kategori untuk menjelaskan benda dan keberadaan.'],['Guṇa merujuk pada…',['Gerak','Sifat atau kualitas','Ketidakadaan'],1,'Guṇa berarti sifat atau kualitas.']]},
 {name:'Sāṃkhya',icon:'🌱',figure:'Rsi Kapila',focus:'Hubungan Puruṣa (kesadaran) dan Prakṛti (prinsip material).',intro:'Sāṃkhya menjelaskan dua prinsip utama, yaitu Puruṣa sebagai kesadaran dan Prakṛti sebagai sumber yang bersifat material.',sections:[['Puruṣa dan Prakṛti','Puruṣa adalah prinsip kesadaran yang menjadi saksi, sedangkan Prakṛti merupakan prinsip material yang mengalami perkembangan.'],['Sifat Sāṃkhya','Sāṃkhya dikenal sebagai aliran dualistik karena menjelaskan realitas melalui dua prinsip tersebut. Dalam bahan yang digunakan, aliran ini disebut Nir Īśvara karena tidak menjadikan Īśvara sebagai penyebab utama alam semesta.'],['Keterikatan','Keterikatan dijelaskan terjadi ketika manusia tidak mampu membedakan Puruṣa dan Prakṛti.'],['Penerapan sehari-hari','Mengenali pengaruh sifat dan emosi, meningkatkan kejernihan berpikir, serta memilih respons secara sadar.']],apply:'Ketika emosi muncul, kenali perasaan itu terlebih dahulu dan pilih respons dengan sadar, bukan sekadar mengikuti dorongan sesaat.',feedback:[['Puruṣa merujuk pada…',['Kesadaran','Benda material','Gerakan tubuh'],0,'Puruṣa adalah prinsip kesadaran.'],['Prakṛti merupakan…',['Cara memperoleh kesaksian','Prinsip material','Nama tokoh Nyāya'],1,'Prakṛti adalah prinsip material yang mengalami perkembangan.'],['Sāṃkhya disebut dualistik karena…',['Membahas dua prinsip utama','Memiliki dua tokoh saja','Hanya membahas ritual'],0,'Dua prinsip utamanya adalah Puruṣa dan Prakṛti.']]},
 {name:'Yoga',icon:'🧘',figure:'Maharsi Patanjali',focus:'Pengendalian pikiran dan praktik spiritual untuk mencapai pembebasan.',intro:'Yoga berasal dari kata yuj yang berarti menghubungkan. Yoga menekankan pengendalian pikiran dan latihan spiritual.',sections:[['Hubungan dengan Sāṃkhya','Yoga memiliki hubungan erat dengan Sāṃkhya. Dalam materi pembelajaran, Yoga menerima 25 Tattwa Sāṃkhya dan menambahkan Īśvara sebagai Puruṣa istimewa.'],['Aṣṭāṅga Yoga','Delapan tahapannya adalah Yama (etika), Niyama (disiplin), Āsana (postur tubuh), Prāṇāyāma (pengaturan napas), Pratyāhāra (pengendalian indra), Dhāraṇā (konsentrasi), Dhyāna (meditasi), dan Samādhi (kesadaran luhur).'],['Tujuan latihan','Latihan dilakukan bertahap untuk membantu pengendalian pikiran, perilaku, indra, dan konsentrasi.'],['Penerapan sehari-hari','Mengatur pikiran, menjaga konsentrasi, melakukan refleksi, dan melatih pengendalian diri melalui kebiasaan baik.']],apply:'Sebelum belajar, atur napas dengan tenang, singkirkan gangguan, lalu arahkan perhatian pada satu tugas.',feedback:[['Tokoh Yoga Darsana adalah…',['Maharsi Patanjali','Rsi Gautama','Badarayana'],0,'Yoga Darsana dikaitkan dengan Maharsi Patanjali.'],['Āsana berarti…',['Etika','Postur tubuh','Konsentrasi'],1,'Āsana adalah postur atau sikap tubuh.'],['Pratyāhāra berkaitan dengan…',['Pengendalian indra','Pengelompokan benda','Penafsiran Weda'],0,'Pratyāhāra merupakan tahap pengendalian indra.']]},
 {name:'Mīmāṃsā',icon:'🪔',figure:'Rsi Jaimini',focus:'Penafsiran Weda, kewajiban, dan pelaksanaan tindakan sesuai ajaran.',intro:'Mīmāṃsā menaruh perhatian pada penafsiran Weda dan makna pelaksanaan kewajiban atau tindakan yang diajarkan di dalamnya.',sections:[['Fokus utama','Mīmāṃsā mempelajari penafsiran ajaran Weda, terutama bagian yang berkaitan dengan kewajiban dan pelaksanaan ritual.'],['Tindakan dan kewajiban','Tindakan dipahami dalam kaitannya dengan ajaran dan kewajiban. Pemahaman terhadap petunjuk perlu dilakukan secara cermat, bukan sekadar mengikuti kebiasaan tanpa mengetahui maknanya.'],['Penafsiran ajaran','Penafsiran membantu memahami maksud suatu petunjuk dan bagaimana petunjuk tersebut diterapkan sesuai konteksnya.'],['Penerapan sehari-hari','Menjalankan tanggung jawab dengan sungguh-sungguh, memahami alasan di balik kewajiban, dan menghormati pedoman yang dipelajari.']],apply:'Ketika menjalankan tanggung jawab, pahami tujuan dan maknanya, lalu laksanakan dengan sungguh-sungguh.',feedback:[['Mīmāṃsā terutama memberi perhatian pada…',['Penafsiran Weda dan kewajiban','Klasifikasi benda','Puruṣa dan Prakṛti'],0,'Mīmāṃsā menekankan penafsiran Weda dan pelaksanaan kewajiban.'],['Tokoh yang dikaitkan dengan Mīmāṃsā adalah…',['Rsi Jaimini','Rsi Kanada','Rsi Kapila'],0,'Mīmāṃsā dikaitkan dengan Rsi Jaimini.'],['Contoh penerapan yang sesuai adalah…',['Menjalankan tanggung jawab dengan memahami maknanya','Menerima semua kabar tanpa memeriksa','Mengabaikan kewajiban'],0,'Memahami dan menjalankan kewajiban dengan sungguh-sungguh merupakan contoh penerapan yang sesuai.']]},
 {name:'Vedānta',icon:'📖',figure:'Badarayana / Sri Wyasa',focus:'Pemahaman tentang hakikat realitas, diri, dan tujuan spiritual.',intro:'Vedānta merupakan salah satu aliran Sad Darsana yang menelaah ajaran filosofis Weda, termasuk hakikat realitas dan diri.',sections:[['Fokus utama','Vedānta mengkaji bagian akhir atau inti filosofis Weda, terutama ajaran yang berkaitan dengan Brahman, Ātman, dan pembebasan sesuai pembahasan dalam sumber belajar.'],['Brahman dan Ātman','Brahman dipahami sebagai realitas tertinggi, sedangkan Ātman berkaitan dengan diri atau jiwa. Penjelasan hubungan keduanya dapat berbeda menurut aliran Vedānta.'],['Tujuan pemahaman','Pembelajaran Vedānta mengajak seseorang merenungkan hakikat diri, realitas, dan tujuan spiritual.'],['Penerapan sehari-hari','Merefleksikan makna hidup, mengembangkan kebijaksanaan, dan mempertimbangkan tindakan berdasarkan pemahaman spiritual.']],apply:'Luangkan waktu untuk merenungkan alasan di balik tindakan dan bagaimana tindakan tersebut mencerminkan nilai yang diyakini.',feedback:[['Vedānta dikaitkan dengan tokoh…',['Badarayana / Sri Wyasa','Rsi Gautama','Rsi Kanada'],0,'Vedānta dikaitkan dengan Badarayana atau Sri Wyasa.'],['Ātman berkaitan dengan…',['Diri atau jiwa','Gerak benda','Cara membandingkan'],0,'Ātman berkaitan dengan diri atau jiwa.'],['Contoh penerapan yang sesuai adalah…',['Merenungkan makna tindakan dan nilai hidup','Mengabaikan refleksi diri','Mengelompokkan benda berdasarkan ukuran saja'],0,'Refleksi tentang diri dan nilai hidup selaras dengan fokus Vedānta.']]}
];
