function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showToast(message){let old=document.querySelector('.mini-toast');if(old)old.remove();const t=document.createElement('div');t.className='mini-toast';t.setAttribute('role','status');t.textContent=message;document.body.appendChild(t);setTimeout(()=>t.remove(),2600)}
function shell(html){app.innerHTML=`<section class="surface"><div class="content">${html}</div></section>`}
function head(kicker,title,sub=''){return `<p class="eyebrow">${kicker}</p><h1 class="display">${title}</h1>${sub?`<p class="lead">${sub}</p>`:''}`}
function syncNavigation(){document.body.classList.toggle('hide-nav', ['intro','identitas','percakapan'].includes(route));}
function go(where){
 if(route==='kuis'&&!quizSubmitted&&where!=='kuis'){
   if(!confirm('Yakin ingin keluar dari kuis? Jawaban yang belum dikumpulkan tidak akan tersimpan.')) return;
   if(quizTimer)clearInterval(quizTimer); quizTimer=null; quizAnswers={}; quizSubmitted=false;
 }
 if(where==='refleksi'&&state.quiz){state.reflectedAfterQuiz=true;saveState()}
 if((route==='hasil'||route==='pembahasan')&&state.quiz&&!state.reflectedAfterQuiz&&where!=='refleksi'&&where!=='hasil'&&where!=='pembahasan'){pendingRoute=where;showReflectionPrompt();return}
 modalRoot.innerHTML=''; route=where; render()
}
function render(){syncNavigation();switch(route){case'intro':return renderIntro();case'identitas':return renderIdentity();case'percakapan':return renderConversation();case'peta':return renderMap();case'pelajaran':return renderLesson();case'umpanbalik':return renderFeedback();case'kuis-interaktif':return renderInteractiveQuiz();case'aktivitas':return renderActivities();case'kuis-intro':return renderQuizIntro();case'kuis':return renderQuiz();case'hasil':return renderResult();case'pembahasan':return renderReview();case'profil':return renderProfile();case'penyusun':return renderMembers();case'petunjuk':return renderInstructions();case'pustaka':return renderSources();case'infografis':return renderInfographics();case'refleksi':return renderReflection();case'kesimpulan':return go('infografis');default:route='intro';return renderIntro()}}
function renderIntro(){shell(`<div class="hero-grid"><div>${head('Media Pembelajaran Interaktif','Jejak <span class="gold">kebijaksanaan.</span>','Pernahkah kamu bertanya-tanya tentang hakikat kehidupan dan kebenaran? Dalam agama Hindu, Darsana mengajak kita memahami dunia melalui pemikiran filosofis. Mari jelajahi Sad Darsana, satu langkah demi satu langkah.')}<div class="actions"><button class="btn" onclick="beginJourney()">Mulai perjalanan →</button></div></div><div class="hero-art"><div class="book-orbit"><div class="book">📖</div></div></div></div><div class="footer-note">Belajar dengan rasa ingin tahu · Bertumbuh dalam kebijaksanaan</div>`)}
function beginJourney(){if(!state.identity){identityReturnRoute='percakapan';route='identitas';render()}else{route='percakapan';introStep=3;render()}}
function renderConversation(){let lines=['Hai! Selamat datang di perjalanan mengenal Darsana.','Kita akan menjelajahi enam aliran filsafat Hindu dan menemukan gagasan yang dekat dengan kehidupan sehari-hari.','Ikuti peta, pelajari materi, dan jawab pertanyaan umpan balik pada setiap materi.','Siap memulai petualangan? Sebelum itu, kenalan dulu, yuk!'];let personalized=!!state.identity;let message=personalized?`Hai, ${escapeHTML(state.identity.nama)}! Senang kamu bergabung dalam Ekspedisi Sad Darsana. Yuk, jelajahi materi, pahami gagasannya, dan temukan kaitannya dengan kehidupan sehari-hari.`:lines[introStep];shell(`<div class="hero-grid"><div class="hero-art"><div class="book-orbit"><div class="book">🧑‍🎓</div></div></div><div><p class="eyebrow">Teman belajar menyapa</p><div class="card"><p style="font-size:1.15rem;margin:0">${message}</p></div><p class="muted small">${personalized?'Perkenalan selesai · Saatnya mulai belajar':`Percakapan ${introStep+1} dari ${lines.length} · Klik tombol untuk lanjut`}</p><div class="actions"><button class="btn" onclick="nextConversation()">${personalized?'Jelajah peta →':introStep===lines.length-1?'Isi identitas →':'Lanjut →'}</button></div></div></div>`)}
function nextConversation(){if(state.identity){route='peta';render();return}if(introStep<3){introStep++;renderConversation()}else{route='identitas';render()}}
function renderIdentity(){
 let d=state.identity||{};
 modalRoot.innerHTML=`<div class="modal-backdrop identity-backdrop"><section class="modal identity-modal"><p class="eyebrow">Sebelum memulai ekspedisi</p><h2>Kenalan dulu, yuk! 👋</h2><p>Isi identitas singkat agar progres dan sertifikatmu tersimpan di browser ini.</p>
 <form onsubmit="saveIdentity(event)">
 <div class="field"><label for="nama">Nama lengkap</label><input id="nama" name="nama" required maxlength="90" value="${escapeHTML(d.nama||'')}" placeholder="Masukkan nama lengkap"></div>
 <div class="field-row"><div class="field"><label for="absen">Nomor absen</label><input id="absen" name="absen" required maxlength="10" value="${escapeHTML(d.absen||'')}" placeholder="Nomor absen"></div><div class="field"><label for="kelas">Kelas</label><input id="kelas" name="kelas" required value="${escapeHTML(d.kelas||'XI B1')}"></div></div>
 <div class="field"><label for="sekolah">Sekolah</label><input id="sekolah" name="sekolah" required value="${escapeHTML(d.sekolah||'SMA Negeri 1 Gianyar')}"></div>
 <h3>Teman belajarmu</h3><div class="avatar-row">${[['🦊','Rubah'],['🐢','Kura-kura'],['🦉','Burung hantu']].map(([a,n])=>`<button type="button" class="avatar-choice ${state.avatar===a?'active':''}" onclick="chooseAvatar('${a}',this)"><span class="animal">${a}</span><strong>${n}</strong></button>`).join('')}</div>
 <div class="actions"><button class="btn" type="submit">Simpan & lanjut →</button></div>
 </form><p class="muted small">Identitas dan progres hanya disimpan pada browser/perangkat ini.</p></section></div>`;
}
function chooseAvatar(a,el){state.avatar=a;document.querySelectorAll('.avatar-choice').forEach(x=>x.classList.remove('active'));el.classList.add('active');saveState()}
function saveIdentity(e){e.preventDefault();const f=new FormData(e.target);state.identity={nama:f.get('nama').trim(),absen:f.get('absen').trim(),kelas:f.get('kelas').trim(),sekolah:f.get('sekolah').trim()};saveState();modalRoot.innerHTML='';route=identityReturnRoute; if(route==='percakapan')introStep=3; render();}
function renderMap(){let done=state.completed.length;let name=state.identity?.nama||'Sahabat Darsana';shell(`${head('Ekspedisi Sad Darsana',`Selamat datang, <span class="gold">${escapeHTML(name.split(' ')[0])}!</span>`,'Jelajahi enam aliran filsafat Hindu secara bertahap. Selesaikan materi dan tiga pertanyaan umpan balik sebelum membuka materi berikutnya.')}<div class="notice expedition-note">🧭 <strong>Catatan ekspedisi:</strong> Materi harus diselesaikan secara berurutan. Aktivitas interaktif dan kuis akhir dapat dikerjakan kapan saja.</div><div class="progress-line compact-progress"><span style="width:${done/6*100}%"></span></div><p class="muted small map-progress-label">Progres materi: ${done} dari 6 tuntas</p><div class="map-grid compact-map-grid">${lessons.map((l,i)=>{let locked=i>0&&!state.completed.includes(i-1);return `<button class="lesson-card compact-lesson ${state.completed.includes(i)?'done':''} ${locked?'locked':''}" onclick="openLesson(${i})" ${locked?'aria-label="Selesaikan materi sebelumnya terlebih dahulu"':''}><span class="number">${String(i+1).padStart(2,'0')}</span><span class="symbol">${locked?'🔒':l.icon}</span><h3>${l.name}</h3><span class="lesson-status">${state.completed.includes(i)?'✓ Tuntas':locked?'Terkunci':'Pelajari →'}</span></button>`}).join('')}</div><button class="activity-banner" onclick="go('aktivitas')"><span class="activity-banner-icon">🧩</span><span><strong>Aktivitas Interaktif</strong><small>Susun huruf acak · Menjodohkan · Benar atau salah</small></span><span class="activity-banner-arrow">→</span></button>`)}
function openLesson(i){const missing=lessons.slice(0,i).findIndex((_,idx)=>!state.completed.includes(idx));if(missing!==-1){showToast(`Selesaikan materi ${lessons[missing].name} terlebih dahulu.`);return}activeLesson=i;feedbackAnswers={};route='pelajaran';render()}
function formatSectionContent(title,text){const listTitles=/Prameya|Pramāṇa|Padārtha|Aṣṭāṅga Yoga|delapan tahap/i;if(listTitles.test(title)){let parts=text.split(/,\s*(?=[A-ZĀĪŪŚṚṆ])/);if(parts.length>2)return `<ul class="material-points">${parts.map(x=>`<li>${x.replace(/\.$/,'')}</li>`).join('')}</ul>`}if(/Pratyakṣa:/.test(text)&&/Anumāna:/.test(text)){return `<ul class="material-points">${text.split(/(?=(?:Pratyakṣa|Anumāna|Upamāna|Śabda):)/).filter(Boolean).map(x=>`<li>${x.trim()}</li>`).join('')}</ul>`}return `<p>${text}</p>`}
function renderLesson(){let l=lessons[activeLesson],done=state.completed.includes(activeLesson);shell(`${head(`Materi ${activeLesson+1} dari 6`,l.name, l.intro)}<div class="grid2"><article class="card tint-sage"><p class="eyebrow">Tokoh</p><h3>${l.figure}</h3><p>${l.focus}</p></article><article class="card tint-peach"><p class="eyebrow">Fokus utama</p><p>${l.apply}</p></article></div><div class="lesson-columns" style="margin-top:20px"><div class="col">${l.sections.slice(0,2).map((s,i)=>`<section class="section-block"><span class="tag">Bagian ${i+1}</span><h3>${s[0]}</h3>${formatSectionContent(s[0],s[1])}</section>`).join('')}</div><div class="col">${l.sections.slice(2).map((s,i)=>`<section class="section-block"><span class="tag">Bagian ${i+3}</span><h3>${s[0]}</h3>${formatSectionContent(s[0],s[1])}</section>`).join('')}</div></div><div class="notice" style="margin-top:22px">${done?'✓ Materi ini sudah tuntas. Kamu tetap boleh membaca kembali dan mengulang umpan balik.':'Langkah berikutnya: jawab tiga pertanyaan umpan balik untuk menuntaskan materi ini.'}</div><div class="actions"><button class="btn secondary" onclick="go('peta')">← Kembali ke peta</button><button class="btn" onclick="openFeedbackPanel()">${done?'Ulangi umpan balik':'Lanjut ke umpan balik'} →</button></div>`)}
function renderFeedback(){openFeedbackPanel()}
function openFeedbackPanel(){renderFeedbackPanel()}
function renderFeedbackPanel(){
 const l=lessons[activeLesson];
 modalRoot.innerHTML=`<div class="drawer-backdrop" onclick="if(event.target===this)closeFeedbackPanel()"><aside class="feedback-drawer" role="dialog" aria-modal="true" aria-label="Kuis dan umpan balik">
 <button class="drawer-close" onclick="closeFeedbackPanel()" aria-label="Tutup">×</button>
 <p class="eyebrow">Cek pemahaman · Materi ${activeLesson+1}/6</p><h2>Umpan balik ${l.name}</h2><p class="muted">Jawab ketiga pertanyaan. Jawaban benar ditandai hijau, sedangkan jawaban yang perlu diperbaiki ditandai merah.</p>
 <div class="progress-line" id="feedback-progress"><span style="width:${Object.keys(feedbackAnswers).length/3*100}%"></span></div>
 ${l.feedback.map((q,i)=>`<article class="card feedback-question ${['tint-sage','tint-peach','tint-blue'][i%3]}" data-feedback-question="${i}"><p class="eyebrow">Pertanyaan ${i+1} dari 3</p><h3>${q[0]}</h3>${q[1].map((o,j)=>`<button id="feedback-${i}-${j}" class="quiz-choice ${feedbackAnswers[i]===j?(j===q[2]?'correct':'incorrect'):''}" ${feedbackAnswers[i]!==undefined?'disabled':''} onclick="answerFeedback(${i},${j})">${String.fromCharCode(65+j)}. ${o}</button>`).join('')}<div id="feedback-note-${i}" class="feedback-note ${feedbackAnswers[i]===undefined?'muted':feedbackAnswers[i]===q[2]?'is-right':'is-wrong'}">${feedbackAnswers[i]===undefined?'Pilih satu jawaban.':(feedbackAnswers[i]===q[2]?'✅ Benar! ':'❌ Belum tepat. ')+q[3]}</div></article>`).join('')}
 <div class="drawer-actions"><button class="btn secondary" onclick="closeFeedbackPanel()">Kembali ke materi</button><button class="btn" onclick="completeFeedback()">Tandai selesai & lanjutkan →</button></div>
 </aside></div>`;
}
function closeFeedbackPanel(){modalRoot.innerHTML=''}
function answerFeedback(i,j){if(feedbackAnswers[i]!==undefined)return;feedbackAnswers[i]=j;const l=lessons[activeLesson],q=l.feedback[i];playAnswerSound(j===q[2]);q[1].forEach((_,k)=>{const b=document.getElementById(`feedback-${i}-${k}`);if(b){b.className='quiz-choice '+(k===j?(j===q[2]?'correct':'incorrect'):'');b.disabled=true}});const note=document.getElementById(`feedback-note-${i}`);if(note){note.className='feedback-note '+(j===q[2]?'is-right':'is-wrong');note.textContent=(j===q[2]?'✅ Benar! ':'❌ Belum tepat. ')+q[3]}const bar=document.querySelector('#feedback-progress span');if(bar)bar.style.width=(Object.keys(feedbackAnswers).length/3*100)+'%';}
function completeFeedback(){if(Object.keys(feedbackAnswers).length<3){alert('Jawab ketiga pertanyaan terlebih dahulu, ya.');return}if(!state.feedbackDone.includes(activeLesson))state.feedbackDone.push(activeLesson);if(!state.completed.includes(activeLesson))state.completed.push(activeLesson);saveState();modalRoot.innerHTML='';route='peta';render()}

const scrambleItems=[{word:'NYAYA',hint:'Aliran yang menekankan logika dan penalaran.'},{word:'YOGA',hint:'Aliran yang menjelaskan Aṣṭāṅga Yoga.'},{word:'VEDANTA',hint:'Aliran yang mengkaji Brahman dan Ātman.'}];
const matchItems=[['Nyāya','Rsi Gautama'],['Vaiśeṣika','Rsi Kanada'],['Sāṃkhya','Rsi Kapila'],['Yoga','Patañjali'],['Mīmāṃsā','Rsi Jaimini'],['Vedānta','Badarayana']];
const truthItems=[['Nyāya menekankan logika dan penalaran.',true],['Puruṣa adalah prinsip material dalam Sāṃkhya.',false],['Aṣṭāṅga Yoga terdiri atas delapan tahapan.',true],['Mīmāṃsā berkaitan dengan penafsiran ajaran Weda.',true],['Vaiśeṣika dikenal dengan kategori Padārtha.',true]];
function renderActivities(){if(activityMode==='scramble')return renderScramble();if(activityMode==='match')return renderMatching();if(activityMode==='truth')return renderTrueFalse();shell(`${head('Belajar sambil bermain','Aktivitas Interaktif','Pilih satu aktivitas untuk menguji pemahaman dengan cara yang berbeda.')}<div class="activity-hub"><button class="card tint-sage activity-choice" onclick="startActivity('scramble')"><span class="step-icon">🔤</span><h3>Susun huruf acak</h3><p>Susun huruf menjadi nama aliran Sad Darsana.</p><span class="btn secondary">Mulai →</span></button><button class="card tint-peach activity-choice" onclick="startActivity('match')"><span class="step-icon">🔗</span><h3>Menjodohkan</h3><p>Pasangkan nama aliran dengan tokohnya.</p><span class="btn secondary">Mulai →</span></button><button class="card tint-lav activity-choice" onclick="startActivity('truth')"><span class="step-icon">☑️</span><h3>Benar atau salah</h3><p>Nilai pernyataan singkat tentang Sad Darsana.</p><span class="btn secondary">Mulai →</span></button></div><div class="actions"><button class="btn secondary" onclick="go('peta')">← Kembali ke Beranda</button></div>`)}
function startActivity(mode){activityMode=mode==='hub'?'hub':mode;activityIndex=0;activityAnswers={};scrambleAnswer='';matchSelected=null;matchedPairs=[];route='aktivitas';render()}
function renderScramble(){const item=scrambleItems[activityIndex%scrambleItems.length];const letters=item.word.split('').sort((a,b)=>((a.charCodeAt(0)*7+activityIndex*13)%19)-((b.charCodeAt(0)*7+activityIndex*13)%19));const solved=activityAnswers[activityIndex]===item.word;shell(`${head('Aktivitas Interaktif','Susun huruf acak','Pilih huruf hingga membentuk nama aliran yang tepat.')}<article class="card tint-sage activity-game"><p class="eyebrow">Tantangan ${activityIndex+1} dari ${scrambleItems.length}</p><h3>${item.hint}</h3><div class="scramble-answer">${scrambleAnswer.split('').join(' ')||'— — —'}</div><div class="scramble-letters">${letters.map((c,i)=>`<button class="letter-tile" onclick="addScrambleLetter('${c}')" ${scrambleAnswer.length>=item.word.length||solved?'disabled':''}>${c}</button>`).join('')}</div>${solved?'<div class="notice success">Benar! Susunan hurufmu tepat.</div>':activityAnswers[activityIndex]===false?'<div class="notice warning">Belum tepat. Coba susun lagi.</div>':''}<div class="actions"><button class="btn secondary" onclick="scrambleAnswer='';renderScramble()">Ulangi</button><button class="btn" onclick="checkScramble()">Periksa</button>${solved?`<button class="btn gold" onclick="nextScramble()">${activityIndex<scrambleItems.length-1?'Berikutnya →':'Selesai'}</button>`:''}</div></article><div class="actions"><button class="btn secondary" onclick="startActivity('hub')">Kembali ke aktivitas</button></div>`)}
function addScrambleLetter(c){if(scrambleAnswer.length<scrambleItems[activityIndex%scrambleItems.length].word.length)scrambleAnswer+=c;renderScramble()}
function checkScramble(){const word=scrambleItems[activityIndex%scrambleItems.length].word;activityAnswers[activityIndex]=scrambleAnswer===word;playAnswerSound(activityAnswers[activityIndex]);renderScramble()}
function nextScramble(){if(activityIndex<scrambleItems.length-1){activityIndex++;scrambleAnswer='';renderScramble()}else{showToast('Aktivitas susun huruf selesai!');startActivity('hub')}}
function renderMatching(){const right=matchItems.map(x=>x[1]);shell(`${head('Aktivitas Interaktif','Menjodohkan tokoh','Pilih nama aliran di sebelah kiri, lalu pilih tokoh yang sesuai di sebelah kanan.')}<article class="card activity-game"><p class="eyebrow">Pasangan benar: ${matchedPairs.length} dari ${matchItems.length}</p><div class="matching-grid"><div>${matchItems.map((x,i)=>`<button class="match-item ${matchSelected===i?'selected':''} ${matchedPairs.includes(i)?'matched':''}" onclick="selectMatch(${i})" ${matchedPairs.includes(i)?'disabled':''}>${x[0]}</button>`).join('')}</div><div>${right.map((name,j)=>{let idx=matchItems.findIndex(x=>x[1]===name);return `<button class="match-item ${matchedPairs.includes(idx)?'matched':''}" onclick="pairMatch(${idx})" ${matchedPairs.includes(idx)?'disabled':''}>${name}</button>`}).join('')}</div></div>${activityAnswers.done?'<div class="notice success">Hebat! Semua pasangan berhasil ditemukan.</div>':''}</article><div class="actions"><button class="btn secondary" onclick="startActivity('match')">Ulangi</button><button class="btn secondary" onclick="startActivity('hub')">Kembali ke aktivitas</button></div>`)}
function selectMatch(i){matchSelected=i;renderMatching()}
function pairMatch(i){if(matchSelected===null){showToast('Pilih nama aliran terlebih dahulu.');return}if(matchSelected===i){matchedPairs.push(i);matchSelected=null;playAnswerSound(true);if(matchedPairs.length===matchItems.length)activityAnswers.done=true}else{playAnswerSound(false);showToast('Pasangan belum tepat, coba lagi.')}renderMatching()}
function renderTrueFalse(){const item=truthItems[activityIndex%truthItems.length],answered=activityAnswers[activityIndex]!==undefined;shell(`${head('Aktivitas Interaktif','Benar atau salah','Baca pernyataan, lalu tentukan apakah isinya benar atau salah.')}<article class="card tint-lav activity-game"><p class="eyebrow">Pernyataan ${activityIndex+1} dari ${truthItems.length}</p><h3 class="truth-statement">${item[0]}</h3>${answered?`<div class="notice ${activityAnswers[activityIndex]===item[1]?'success':'warning'}">${activityAnswers[activityIndex]===item[1]?'Tepat!':'Belum tepat.'} ${item[1]?'Pernyataan ini benar.':'Pernyataan ini salah.'}</div>`:''}<div class="actions"><button class="btn secondary" onclick="answerTruth(true)" ${answered?'disabled':''}>Benar</button><button class="btn secondary" onclick="answerTruth(false)" ${answered?'disabled':''}>Salah</button>${answered?`<button class="btn gold" onclick="nextTruth()">${activityIndex<truthItems.length-1?'Berikutnya →':'Selesai'}</button>`:''}</div></article><div class="actions"><button class="btn secondary" onclick="startActivity('hub')">Kembali ke aktivitas</button></div>`)}
function answerTruth(v){activityAnswers[activityIndex]=v;playAnswerSound(v===truthItems[activityIndex%truthItems.length][1]);renderTrueFalse()}
function nextTruth(){if(activityIndex<truthItems.length-1){activityIndex++;renderTrueFalse()}else{showToast('Aktivitas benar atau salah selesai!');startActivity('hub')}}

function openInteractiveQuiz(){startActivity('hub')}
function renderInteractiveQuiz(){
 const bank=quizBank.slice(0,6),q=bank[practiceIndex],ans=practiceAnswers[practiceIndex],answered=ans!==undefined;
 shell(`${head('Latihan interaktif','Kuis kilat Sad Darsana','Latihan 6 soal tanpa batas waktu. Kamu langsung mendapat umpan balik setelah memilih jawaban.')}<div class="quiz-head"><span>Soal ${practiceIndex+1} dari ${bank.length}</span><span class="pill">Latihan · tanpa timer</span></div><div class="progress-line"><span style="width:${(practiceIndex+1)/bank.length*100}%"></span></div><article class="card ${['tint-sage','tint-peach','tint-blue','tint-lav'][practiceIndex%4]}" style="margin-top:20px"><p class="eyebrow">Pertanyaan ${practiceIndex+1}</p><div class="question">${q[0]}</div>${q[1].map((o,i)=>`<button class="quiz-choice ${answered&&i===q[2]?'correct':answered&&ans===i&&i!==q[2]?'incorrect':''}" ${answered?'disabled':''} onclick="choosePractice(${i})">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}${answered?`<div class="notice ${ans===q[2]?'success':'warning'}">${ans===q[2]?'🎉 Tepat!':'💡 Belum tepat, tidak apa-apa.'} ${q[3]}</div>`:''}</article><div class="actions"><button class="btn secondary" onclick="go('peta')">← Kembali ke peta</button>${practiceIndex>0?'<button class="btn secondary" onclick="practiceIndex--;renderInteractiveQuiz()">Sebelumnya</button>':''}${answered?(practiceIndex<bank.length-1?'<button class="btn" onclick="practiceIndex++;renderInteractiveQuiz()">Soal berikutnya →</button>':`<button class="btn gold" onclick="finishPractice()">Lihat hasil latihan →</button>`):''}</div>`);
}
function choosePractice(i){const q=quizBank.slice(0,6)[practiceIndex];practiceAnswers[practiceIndex]=i;playAnswerSound(i===q[2]);renderInteractiveQuiz()}
function finishPractice(){const bank=quizBank.slice(0,6),correct=bank.reduce((n,q,i)=>n+(practiceAnswers[i]===q[2]?1:0),0);shell(`${head('Latihan selesai','Bagus, kamu sudah berlatih!','Latihan ini tidak memengaruhi nilai kuis akhir.')}<div class="card tint-lav" style="text-align:center"><div class="display" style="font-size:4rem;margin:0">${correct}/${bank.length}</div><p class="lead" style="margin:10px auto">${correct===6?'Keren! Semua jawabanmu tepat.':correct>=4?'Bagus! Cek kembali pembahasan soal yang belum tepat.':'Yuk, baca materi dan coba latihan sekali lagi.'}</p></div><div class="actions"><button class="btn secondary" onclick="openInteractiveQuiz()">Ulangi latihan</button><button class="btn" onclick="showQuizIntro()">Lanjut ke kuis akhir →</button><button class="btn secondary" onclick="go('peta')">Kembali ke peta</button></div>`)}
function showQuizIntro(){if(route==='kuis'&&!quizSubmitted){if(!confirm('Yakin ingin keluar dari kuis? Jawaban yang belum dikumpulkan tidak akan tersimpan.'))return;if(quizTimer)clearInterval(quizTimer);quizTimer=null;quizAnswers={};quizSubmitted=false;}route='kuis-intro';render()}
function renderQuizIntro(){shell(`${head('Kuis akhir','Uji pengetahuanmu','Periksa aturan singkat sebelum memulai.')}<article class="card quiz-rules-compact"><div class="quiz-rule-row"><span>📝</span><div><strong>15 soal pilihan ganda</strong><p>Materi Darsana dan enam aliran Sad Darsana.</p></div></div><div class="quiz-rule-row"><span>⏱️</span><div><strong>Waktu 30 menit</strong><p>Timer dimulai setelah tombol mulai ditekan.</p></div></div><div class="quiz-rule-row"><span>📊</span><div><strong>Hasil dan pembahasan</strong><p>Nilai, penjelasan jawaban, dan sertifikat ditampilkan setelah selesai.</p></div></div><p class="muted small">Kuis akhir dapat diakses kapan saja, tetapi pelajari materi terlebih dahulu agar lebih siap.</p></article><div class="actions"><button class="btn secondary" onclick="go('peta')">Nanti dulu</button><button class="btn gold" onclick="startQuiz()">Mulai kuis 30 menit →</button></div>`)}
function startQuiz(){quizIndex=0;quizAnswers={};quizStart=Date.now();quizSubmitted=false;if(quizTimer)clearInterval(quizTimer);quizTimer=setInterval(()=>{if(route==='kuis'){const el=$('#clock');if(el)el.textContent=fmt(remaining());if(Date.now()-quizStart>=1800000){clearInterval(quizTimer);submitQuiz(true)}}},500);route='kuis';render()}
function remaining(){return Math.max(0,1800-Math.floor((Date.now()-quizStart)/1000))}function fmt(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function renderQuiz(){let q=quizBank[quizIndex];shell(`${head('Kuis akhir','Uji pengetahuanmu','Jawab 15 soal pilihan ganda. Waktu pengerjaan tersedia selama 30 menit. Skor dan pembahasan ditampilkan setelah kuis dikumpulkan.')}<div class="quiz-head"><span>Soal ${quizIndex+1} dari ${quizBank.length}</span><span>Waktu tersisa: <strong id="clock">${fmt(remaining())}</strong></span></div><div class="progress-line"><span style="width:${(quizIndex+1)/quizBank.length*100}%"></span></div><div class="question">${quizIndex+1}. ${q[0]}</div>${q[1].map((o,i)=>`<button class="quiz-choice ${quizAnswers[quizIndex]===i?'selected':''}" onclick="chooseQuiz(${i})">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}<div class="actions"><button class="btn secondary" onclick="quizIndex=Math.max(0,quizIndex-1);renderQuiz()" ${quizIndex===0?'disabled':''}>← Sebelumnya</button><button class="btn secondary" onclick="quizIndex=Math.min(quizBank.length-1,quizIndex+1);renderQuiz()" ${quizIndex===quizBank.length-1?'disabled':''}>Berikutnya →</button><button class="btn gold" onclick="submitQuiz(false)">Kumpulkan kuis</button></div><p class="muted small">Jawaban tersimpan selama pengerjaan kuis pada halaman ini. Pastikan semua jawaban sudah diperiksa sebelum dikumpulkan.</p>`);let el=$('#clock');if(el){const update=()=>{if($('#clock'))$('#clock').textContent=fmt(remaining())};update()}}
function chooseQuiz(i){quizAnswers[quizIndex]=i;renderQuiz()}
function submitQuiz(timeout){if(quizSubmitted)return;let missing=quizBank.filter((q,i)=>quizAnswers[i]===undefined).length;if(!timeout&&missing&&!confirm(`Masih ada ${missing} soal yang belum dijawab. Tetap kumpulkan kuis?`))return;quizSubmitted=true;if(quizTimer)clearInterval(quizTimer);let correct=quizBank.reduce((n,q,i)=>n+(quizAnswers[i]===q[2]?1:0),0),score=Math.round(correct/quizBank.length*100);let pred=score>=90?'Istimewa':score>=80?'Sangat Baik':score>=70?'Baik':score>=60?'Cukup':'Terus Bertumbuh';state.quiz={correct,score,answered:Object.keys(quizAnswers).length,total:quizBank.length,predikat:pred,date:new Date().toISOString(),elapsed:Math.min(1800,Math.floor((Date.now()-quizStart)/1000)),answers:{...quizAnswers}};state.certificate={...state.quiz,identity:{...state.identity},avatar:state.avatar};state.reflectedAfterQuiz=false;saveState();route='hasil';render()}
function renderResult(){let q=state.quiz;if(!q){route='kuis-intro';return renderQuizIntro()}let msg=q.score>=90?'Keren banget! Pemahamanmu kuat sekali.':q.score>=80?'Hebat! Kamu sudah memahami banyak hal.':q.score>=70?'Bagus! Sedikit lagi pemahamanmu makin mantap.':q.score>=60?'Kamu sudah punya bekal. Yuk, cek pembahasan dan kuatkan lagi materi.':'Tidak apa-apa, proses belajar memang bertahap. Baca pembahasan, lalu coba lagi saat siap.';shell(`${head('Hasil kuis','Kamu berhasil menyelesaikan kuis!','Lihat hasilmu dulu, lalu buka pembahasan untuk memahami jawaban yang tepat.')}<div class="card tint-sage" style="text-align:center;padding:30px"><p class="eyebrow">Skor akhir</p><div class="display" style="font-size:5rem;margin:0">${q.score}</div><p class="lead" style="margin:10px auto">${msg}</p><span class="pill">Predikat: ${q.predikat}</span></div><div class="stat-grid" style="margin-top:18px"><div class="stat"><strong>${q.correct}</strong><span>Benar</span></div><div class="stat"><strong>${q.total-q.correct}</strong><span>Salah/kosong</span></div><div class="stat"><strong>${q.answered}/${q.total}</strong><span>Terjawab</span></div></div><div class="actions"><button class="btn secondary" onclick="go('pembahasan')">Lihat pembahasan</button><button class="btn gold" onclick="go('sertifikat')">Lihat sertifikat 🏅</button><button class="btn" onclick="startQuiz()">Coba lagi</button></div><p class="muted small">Jika kamu berpindah ke halaman lain, akan muncul pilihan untuk mengisi refleksi sekarang atau nanti.</p>`);}
function renderReview(){let q=state.quiz;if(!q){route='peta';return renderMap()}shell(`${head('Koreksi pemahaman','Pembahasan jawaban','Periksa jawaban yang benar dan alasan singkatnya. Kamu bisa kembali ke hasil kapan saja.')}<div>${quizBank.map((item,i)=>{let ans=q.answers[i],ok=ans===item[2];return `<article class="review-row"><p class="eyebrow">Soal ${i+1} · <span style="color:${ok?'#347b43':'#bd4e40'}">${ok?'BENAR':'PELAJARI LAGI'}</span></p><h3>${item[0]}</h3><p><strong>Jawabanmu:</strong> ${ans===undefined?'Belum dijawab':item[1][ans]}</p><p><strong>Jawaban tepat:</strong> ${item[1][item[2]]}</p><p>${item[3]}</p></article>`}).join('')}</div><div class="actions"><button class="btn secondary" onclick="go('hasil')">← Kembali ke hasil</button><button class="btn gold" onclick="go('sertifikat')">Sertifikat →</button><button class="btn" onclick="go('peta')">Ke peta</button></div>`)}
function showReflectionPrompt(){modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal"><p class="eyebrow">Sebelum melanjutkan</p><h2>Waktunya refleksi singkat 🌱</h2><p>Kamu sudah melihat hasil kuis. Mau meluangkan waktu sebentar untuk merefleksikan pengalaman belajarmu?</p><div class="actions"><button class="btn" onclick="state.reflectedAfterQuiz=true;saveState();modalRoot.innerHTML='';route='refleksi';render()">Isi refleksi sekarang</button><button class="btn secondary" onclick="state.reflectedAfterQuiz=true;saveState();modalRoot.innerHTML='';route=pendingRoute||'peta';pendingRoute=null;render()">Nanti saja</button></div></section></div>`}
function renderReflection(){let r=state.reflections||{};shell(`${head('Refleksi diri','Apa yang kamu bawa pulang?','Tidak ada jawaban benar atau salah. Tuliskan pemikiranmu dengan jujur.')}<div class="field"><label for="r1">1. Gagasan Sad Darsana apa yang paling menarik bagimu? Mengapa?</label><textarea id="r1" placeholder="Tuliskan refleksimu di sini…">${escapeHTML(r.r1||'')}</textarea></div><div class="field"><label for="r2">2. Bagaimana kamu dapat menghubungkan salah satu gagasan dengan kehidupan sehari-hari?</label><textarea id="r2" placeholder="Berikan contoh sederhana…">${escapeHTML(r.r2||'')}</textarea></div><div class="field"><label for="r3">3. Apa hal baru yang kamu pahami setelah menggunakan MPI ini?</label><textarea id="r3" placeholder="Ceritakan hal yang kamu pelajari…">${escapeHTML(r.r3||'')}</textarea></div><div class="actions"><button class="btn secondary" onclick="go('peta')">Kembali</button><button class="btn" onclick="saveReflection()">Simpan refleksi →</button></div><p class="muted small">Jawaban disimpan pada browser di perangkat ini.</p>`)}
function saveReflection(){state.reflections={r1:$('#r1').value,r2:$('#r2').value,r3:$('#r3').value,updated:new Date().toISOString()};saveState();alert('Refleksimu sudah tersimpan pada perangkat ini. Terima kasih!');route='peta';render()}
function renderProfile(){let d=state.identity;if(!d){shell(`${head('Profil pengguna','Belum ada identitas','Isi identitas terlebih dahulu untuk menyimpan progres belajar.')}<button class="btn" onclick="route='identitas';render()">Isi identitas →</button>`);return}let q=state.quiz;let cert=state.certificate;shell(`${head('Profil & progres','Ruang belajarmu','Identitas, progres materi, hasil kuis, dan sertifikat yang tersimpan di browser ini.')}<div class="card tint-sage"><div class="profile-head"><div class="profile-avatar">${state.avatar}</div><div><h2 style="margin:0">${escapeHTML(d.nama)}</h2><p class="muted" style="margin:4px 0">Absen ${escapeHTML(d.absen)} · ${escapeHTML(d.kelas)}</p><p class="muted" style="margin:0">${escapeHTML(d.sekolah)}</p></div></div><div class="actions"><button class="btn secondary" onclick="identityReturnRoute='profil';route='identitas';render()">Ubah identitas</button><button class="btn secondary" onclick="resetProgress()">Ganti pengguna / mulai ulang</button></div></div><div class="grid2" style="margin-top:18px"><article class="card"><p class="eyebrow">Progres materi</p><div class="display" style="font-size:3rem;margin:0">${state.completed.length}/6</div><div class="progress-line"><span style="width:${state.completed.length/6*100}%"></span></div><p>${state.completed.length===6?'Semua materi tuntas!':'Lanjutkan materi yang belum selesai.'}</p></article><article class="card tint-peach"><p class="eyebrow">Kuis akhir</p>${q?`<div class="display" style="font-size:3rem;margin:0">${q.score}/100</div><p>${q.predikat} · ${new Date(q.date).toLocaleDateString('id-ID')}</p>`:'<h3>Belum dikerjakan</h3><p>Nilai kuis akan tampil di sini setelah selesai.</p>'}</article></div><h2 style="margin-top:28px">Sertifikat saya</h2>${cert?`<div class="card"><p>🏅 Sertifikat kuis akhir · Predikat <strong>${cert.predikat}</strong></p><div class="actions"><button class="btn" onclick="go('sertifikat')">Lihat sertifikat</button><button class="btn secondary" onclick="downloadPNG()">Unduh PNG</button><button class="btn secondary" onclick="downloadPDF()">Unduh PDF / Cetak</button></div></div>`:'<div class="card"><p>Sertifikat akan muncul di sini setelah kamu menyelesaikan kuis akhir.</p></div>'}<h2 style="margin-top:28px">Status materi</h2><div class="grid2">${lessons.map((l,i)=>`<article class="card"><h3>${l.icon} ${l.name}</h3><p>${state.completed.includes(i)?'✓ Tuntas':'Belum tuntas'}</p></article>`).join('')}</div>`)}
function resetProgress(){if(!confirm('Hapus identitas, progres, hasil kuis, refleksi, dan sertifikat dari browser ini?'))return;localStorage.removeItem(STORE);state=loadState();route='intro';render()}
function renderCertificate(){let c=state.certificate;if(!c){shell(`${head('Reward','Sertifikat belum tersedia','Selesaikan kuis akhir terlebih dahulu untuk memperoleh sertifikat.')}<button class="btn" onclick="showQuizIntro()">Mulai kuis →</button>`);return}let d=c.identity||state.identity||{};shell(`${head('Penghargaan digital','Sertifikat pencapaian','Kamu dapat mengunduh sertifikat sebagai PNG atau menyimpannya menjadi PDF.')}<div id="certificate" class="cert-preview"><p class="eyebrow">MEDIA PEMBELAJARAN INTERAKTIF · SAD DARSANA</p><div style="font-size:42px">🏅 ✦ 📖 ✦ 🏅</div><h2>SERTIFIKAT PENCAPAIAN</h2><p>Dengan bangga diberikan kepada</p><div class="cert-name">${escapeHTML(d.nama||'Nama Pengguna')}</div><p>atas partisipasi dalam kuis akhir MPI Darsana<br><strong>“Jejak Kebijaksanaan: Ekspedisi Sad Darsana”</strong></p><div style="display:flex;justify-content:center;gap:32px;flex-wrap:wrap;margin:22px 0"><div><div style="font-size:2rem;font-weight:800;color:#9a702d">${c.score}/100</div><small>Nilai kuis</small></div><div><div style="font-size:1.2rem;font-weight:800;color:#315b43">${escapeHTML(c.predikat)}</div><small>Predikat</small></div></div><p>${escapeHTML(d.kelas||'XI B1')} · ${escapeHTML(d.sekolah||'SMA Negeri 1 Gianyar')}</p><p style="font-size:.9rem">Tanggal: ${new Date(c.date).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}</p><p style="color:#a27c39;font-family:'Playfair Display',serif">Terus belajar, bertumbuh, dan menemukan kebijaksanaan.</p></div><div class="actions" style="justify-content:center"><button class="btn" onclick="downloadPNG()">Unduh PNG ↓</button><button class="btn gold" onclick="downloadPDF()">Simpan sebagai PDF ↓</button><button class="btn secondary" onclick="go('profil')">Kembali ke profil</button></div><p class="muted small">Untuk PDF, pilih “Save as PDF / Simpan sebagai PDF” pada dialog cetak yang muncul.</p>`)}
function downloadPNG(){const c=state.certificate;if(!c){alert('Selesaikan kuis akhir terlebih dahulu.');return}const d=c.identity||state.identity||{};const cv=document.createElement('canvas');cv.width=1600;cv.height=1100;const x=cv.getContext('2d');x.fillStyle='#fffaf0';x.fillRect(0,0,1600,1100);x.strokeStyle='#c5a35e';x.lineWidth=12;x.strokeRect(38,38,1524,1024);x.lineWidth=3;x.strokeRect(58,58,1484,984);x.textAlign='center';x.fillStyle='#426b4d';x.font='bold 28px Georgia';x.fillText('MEDIA PEMBELAJARAN INTERAKTIF · SAD DARSANA',800,160);x.font='64px serif';x.fillText('🏅  ✦  📖  ✦  🏅',800,255);x.fillStyle='#183f32';x.font='bold 64px Georgia';x.fillText('SERTIFIKAT PENCAPAIAN',800,365);x.font='30px Arial';x.fillStyle='#555';x.fillText('Dengan bangga diberikan kepada',800,450);x.fillStyle='#9a702d';x.font='bold 58px Georgia';x.fillText(d.nama||'Nama Pengguna',800,540);x.fillStyle='#33382e';x.font='30px Arial';x.fillText('atas partisipasi dalam kuis akhir MPI Darsana',800,610);x.font='bold 34px Arial';x.fillText('“Jejak Kebijaksanaan: Ekspedisi Sad Darsana”',800,660);x.fillStyle='#9a702d';x.font='bold 58px Arial';x.fillText(`${c.score}/100`,610,770);x.fillStyle='#315b43';x.font='bold 38px Arial';x.fillText(c.predikat,1000,770);x.fillStyle='#555';x.font='26px Arial';x.fillText('NILAI KUIS',610,815);x.fillText('PREDIKAT',1000,815);x.font='26px Arial';x.fillText(`${d.kelas||'XI B1'} · ${d.sekolah||'SMA Negeri 1 Gianyar'}`,800,890);x.fillText(`Tanggal: ${new Date(c.date).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}`,800,940);x.fillStyle='#a27c39';x.font='italic 28px Georgia';x.fillText('Terus belajar, bertumbuh, dan menemukan kebijaksanaan.',800,1000);cv.toBlob(blob=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Sertifikat-MPI-Darsana.png';a.click();URL.revokeObjectURL(a.href)},'image/png')}
function downloadPDF(){const el=$('#certificate');if(!el){route='sertifikat';render();setTimeout(downloadPDF,100);return}const w=window.open('','_blank');if(!w){alert('Izinkan pop-up pada browser untuk membuat PDF.');return}w.document.write(`<!doctype html><html><head><title>Sertifikat MPI Darsana</title><style>body{font-family:Georgia,serif;background:#fffaf0;color:#264735;margin:0;padding:28px}.cert{border:8px double #c5a35e;text-align:center;padding:50px 30px;min-height:70vh;display:flex;flex-direction:column;justify-content:center}h1{font-size:32px}.name{font-size:32px;color:#9a702d;border-bottom:1px solid #d9c28e;display:inline-block;padding:12px 20px}@page{size:A4 landscape;margin:10mm}@media print{body{padding:0}.cert{min-height:175mm}}</style></head><body><div class="cert"><p>MEDIA PEMBELAJARAN INTERAKTIF · SAD DARSANA</p><div style="font-size:40px">🏅 ✦ 📖 ✦ 🏅</div><h1>SERTIFIKAT PENCAPAIAN</h1><p>Dengan bangga diberikan kepada</p><div class="name">${escapeHTML((state.certificate?.identity||state.identity||{}).nama||'Nama Pengguna')}</div><p>atas partisipasi dalam kuis akhir MPI Darsana<br><strong>“Jejak Kebijaksanaan: Ekspedisi Sad Darsana”</strong></p><h2>${state.certificate?.score||0}/100 · ${escapeHTML(state.certificate?.predikat||'')}</h2><p>${escapeHTML((state.certificate?.identity||state.identity||{}).kelas||'XI B1')} · ${escapeHTML((state.certificate?.identity||state.identity||{}).sekolah||'SMA Negeri 1 Gianyar')}</p><p>Tanggal: ${new Date(state.certificate?.date||Date.now()).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}</p><p>Terus belajar, bertumbuh, dan menemukan kebijaksanaan.</p></div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function renderMembers(){const members=[['Desak Made Cantika Wulan Dewi','03'],['Kadek Kesya Dwi Navisia','18'],['Ni Kadek Piran Basia Clarita','24'],['Ni Komang Tri Aprilia','26'],['Ni Made Ayudia Nada Paramitha','29'],['Ni Putu Febyana Adelia','34'],['Ni Wayan Yuska Wina Swasti','37'],['Nyoman Ria Sawitri Paramita','38']];shell(`${head('Di balik MPI','Para penyusun','Media ini dikembangkan melalui kerja sama dan proses belajar bersama.')}<div class="compact-list">${members.map((m,i)=>`<article class="member-strip tint-${['sage','peach','blue','lav'][i%4]}"><span class="member-number">${m[1]}</span><span>${m[0]}</span></article>`).join('')}</div>`)}
function renderInstructions(){let steps=[['1','Tekan Mulai perjalanan untuk memulai MPI.'],['2','Ikuti pengantar dan isi identitas agar progres tersimpan di browser ini.'],['3','Pilih materi Sad Darsana pada peta secara berurutan.'],['4','Baca materi dan jawab tiga pertanyaan umpan balik sampai tuntas.'],['5','Gunakan infografis dan sumber belajar untuk memperkuat pemahaman.'],['6','Kerjakan kuis akhir, lalu lihat pembahasan dan sertifikat hasil belajar.'],['7','Isi refleksi setelah kuis atau buka menu Refleksi kapan saja.']];shell(`${head('Panduan singkat','Cara menggunakan MPI','Ikuti langkah sederhana berikut untuk menikmati perjalanan belajar.')}<div class="compact-list instruction-list">${steps.map(s=>`<article class="instruction-strip"><span class="instruction-number">${s[0]}</span><p>${s[1]}</p></article>`).join('')}</div>`)}
function renderSources(){shell(`${head('Sumber belajar','Daftar sumber','Buku dan PDF yang menjadi rujukan materi MPI Darsana.')}<article class="card tint-sage source-card"><div class="step-icon">📚</div><h3>Buku Ajar Darsana</h3><p>Ida Bagus Wika Krishna. (2022). <em>Buku Ajar Darsana.</em></p><a class="btn secondary" href="Buku_Ajar_Darsana.pdf" target="_blank" rel="noopener">Buka PDF Buku Ajar Darsana ↗</a></article><article class="card tint-peach source-card"><div class="step-icon">📖</div><h3>Pendidikan Agama Hindu dan Budi Pekerti untuk Siswa SMA/SMK Kelas XI – Semester Ganjil</h3><p>Ketua penyusun: I Kadek Arta Jaya, S. Ag., M.Pd.H. (2026).</p></article>`)}
function renderInfographics(){const colors=['tint-sage','tint-peach','tint-blue','tint-lav'];const keywords=[['Logika','Pramāṇa','Penalaran'],['Padārtha','Atom','Kategori'],['Puruṣa','Prakṛti','Dualisme'],['Aṣṭāṅga','Disiplin','Konsentrasi'],['Weda','Kewajiban','Penafsiran'],['Brahman','Ātman','Pembebasan']];shell(`${head('Ringkasan visual','Infografis Sad Darsana','Enam aliran, enam sudut pandang untuk memahami pengetahuan, realitas, dan kehidupan.')}<div class="infographic-banner"><div class="infographic-center">🕉️</div><strong>SAD DARSANA</strong><span>Enam sistem filsafat Hindu</span><div class="infographic-line"></div></div><div class="infographic-grid">${lessons.map((l,i)=>`<article class="infographic-card ${colors[i%4]}"><div class="infographic-top"><span class="infographic-number">0${i+1}</span><span class="infographic-symbol">${l.icon}</span></div><h2>${l.name}</h2><p class="infographic-person">Tokoh: <strong>${l.figure}</strong></p><p>${l.focus}</p><div class="keyword-list">${keywords[i].map(k=>`<span>${k}</span>`).join('')}</div></article>`).join('')}</div><p class="muted small infographic-footnote">Ringkasan visual untuk membantu mengingat ciri utama setiap aliran. Buka menu Materi pada Beranda untuk membaca uraian lengkap.</p>`)}
function renderConclusion(){if(state.completed.length<6){shell(`${head('Kesimpulan','Masih terkunci 🔒','Selesaikan keenam materi dan tiga pertanyaan umpan balik pada setiap materi untuk membuka kesimpulan.')}<div class="progress-line"><span style="width:${state.completed.length/6*100}%"></span></div><p>${state.completed.length} dari 6 materi telah tuntas.</p><button class="btn" onclick="go('peta')">Kembali ke peta →</button>`);return}shell(`${head('Inti perjalanan','Benang merah kebijaksanaan','Enam aliran Sad Darsana menawarkan cara pandang yang beragam untuk memahami pengetahuan, realitas, diri, kewajiban, dan pembebasan.')}<div class="grid2">${lessons.map(l=>`<article class="card"><h3>${l.icon} ${l.name}</h3><p>${l.focus}</p></article>`).join('')}</div><div class="notice" style="margin-top:18px">Penalaran, pengamatan, pengendalian diri, tanggung jawab, dan refleksi dapat menjadi pintu untuk menghubungkan materi dengan pengalaman sehari-hari.</div><div class="actions"><button class="btn secondary" onclick="go('peta')">Kembali ke peta</button><button class="btn" onclick="showQuizIntro()">Coba kuis akhir →</button></div>`)}
// Sertifikat uses a dedicated route while keeping the navigation consistent.
const originalRender=render;
// Wrap route dispatch for certificate page.
const _render=render;
render=function(){if(route==='sertifikat')return renderCertificate();return _render()};
render();
